void DrawIcon(uint16_t x,uint16_t y)
{
    int i,j;
    for(i=0;i<100;i++)
    {
      for(j=0;j<100;j++)
      {
         ili9488_SetDisplayWindow(j+x,i+y,1,1);
         LCD_IO_WriteReg(LCD_REG_MEMWR);
         LCD_IO_WriteData(getPixelColor(_acicon_upgrade[i*100+j]));
        
      }
    }
}